    state_parameters, moments, infinity_norms, t = _AdamaxParser(text).parse()
    for buffer in infinity_norms:
        values = buffer if isinstance(buffer, list) else [buffer]
        for value in values:
            if value < 0.0:
                raise ValueError("state u must be non-negative")
